    function showToast(title, message, type) {
        const container = document.getElementById("toast-container");
        if (!container) return;
        const el = document.createElement("div");
        const borderColor = type === "security" ? "border-red-500 bg-red-950/95" :
                            type === "success" ? "border-amber-400 bg-slate-900/95" :
                            "border-sky-400 bg-slate-900/95";
        el.className = `sans-ui border-l-4 ${borderColor} text-white px-4 py-3 rounded shadow-2xl max-w-md transition-all duration-300`;
        el.innerHTML = `
            <div class="font-bold text-sm flex items-center gap-2">
                <span>${type === "security" ? "🛡️ コンテンツ保護作動" : "✅ システム通知"}</span>
                <span>${title}</span>
            </div>
            <div class="text-xs text-gray-200 mt-1 leading-relaxed">${message}</div>
        `;
        container.appendChild(el);
        setTimeout(() => {
            el.style.opacity = "0";
            setTimeout(() => el.remove(), 300);
        }, 4200);
    }

